# -*- coding: utf-8 -*-
AB = "Antibiotiques"
MOL = {
"amoxicilline": ("Amoxicilline", AB, "Pénicillines", "Bêta-lactamine : inhibe la synthèse de la paroi bactérienne (liaison aux PLP), bactéricide ; spectre élargi aux Gram + et à certains Gram −.", "Infections ORL et respiratoires (otite, sinusite, pneumonie non grave), infections urinaires, infections cutanées, fièvre typhoïde, éradication d'H. pylori (association).", "Adulte 500 mg à 1 g 3x/j ; enfant 25-50 mg/kg/j en 2-3 prises (pneumonie : 40-50 mg/kg/j en 2 prises, 3 à 5 jours).", "CI : allergie aux pénicillines. Rash, diarrhée ; adapter en insuffisance rénale."),
"amoxicilline-clavulanate": ("Amoxicilline + Acide clavulanique", AB, "Pénicillines + inhibiteur de bêta-lactamase", "Amoxicilline bactéricide associée à l'acide clavulanique, inhibiteur de bêta-lactamases, qui restaure l'activité sur les germes producteurs de pénicillinase.", "Infections respiratoires, ORL, urinaires, cutanées et gynécologiques, morsures, infections abdominales et dentaires d'origine mixte.", "Adulte 500/125 mg ou 875/125 mg 2-3x/j au repas ; enfant 45-80 mg/kg/j (amoxicilline) en 2-3 prises ; forme IV 1 g/200 mg toutes les 8 h.", "CI : allergie aux pénicillines, antécédent d'ictère/hépatite à l'association. Diarrhée, hépatite cholestatique rare ; adapter en insuffisance rénale."),
"ampicilline": ("Ampicilline", AB, "Pénicillines", "Aminopénicilline bactéricide (inhibition de la synthèse du peptidoglycane) ; spectre étendu à Listeria, entérocoques, H. influenzae et entérobactéries sensibles.", "Méningite néonatale et infections néonatales (avec gentamicine), septicémie, infections urinaires et respiratoires sévères, endocardite (association).", "Adulte 1-2 g IV/IM toutes les 4-6 h ; nouveau-né 50 mg/kg 2-3x/j selon l'âge ; enfant 100-200 mg/kg/j en 4 doses.", "CI : allergie aux pénicillines. Rash, diarrhée ; adapter en insuffisance rénale."),
"benzylpenicilline": ("Benzylpénicilline (pénicilline G)", AB, "Pénicillines", "Pénicilline naturelle bactéricide, inhibe la synthèse de la paroi ; très active sur streptocoques, pneumocoque, méningocoque, tréponème, clostridies.", "Pneumonie et méningite à germes sensibles, septicémie néonatale, syphilis, gangrène gazeuse, tétanos, fièvre puerpérale.", "Adulte 2-4 M UI IV toutes les 4-6 h (jusqu'à 24 M UI/j en méningite) ; enfant 100 000-250 000 UI/kg/j en 4-6 doses.", "CI : allergie aux pénicillines (choc anaphylactique possible). Convulsions à forte dose en insuffisance rénale ; apport sodique/potassique."),
"benzathine-benzylpenicilline": ("Benzathine benzylpénicilline", AB, "Pénicillines", "Pénicilline G à libération prolongée (dépôt IM) assurant des taux sériques bas mais durables ; bactéricide sur streptocoques A et tréponème.", "Syphilis, prévention du rhumatisme articulaire aigu, angine à streptocoque A, pian.", "Adulte 2,4 M UI IM en dose unique (syphilis précoce) ; angine : 1,2 M UI IM (2,4 M UI selon poids/protocole) ; prophylaxie du RAA toutes les 3-4 semaines.", "Voie IM profonde stricte, jamais IV (arrêt cardiaque). CI : allergie aux pénicillines. Douleur au point d'injection."),
"phenoxymethylpenicilline": ("Phénoxyméthylpénicilline (pénicilline V)", AB, "Pénicillines", "Pénicilline orale bactéricide, inhibe la synthèse de la paroi bactérienne ; spectre étroit sur streptocoques et pneumocoque.", "Angine à streptocoque A, prévention du rhumatisme articulaire aigu, infections ORL et dentaires légères, érysipèle (relais).", "Adulte 1 MUI (≈ 650 mg) 2-3x/j 10 jours (angine) ; enfant 25-50 mg/kg/j en 2-4 prises ; prendre à jeun.", "CI : allergie aux pénicillines. Troubles digestifs, rash."),
"cloxacilline": ("Cloxacilline", AB, "Pénicillines du groupe M (anti-staphylococciques)", "Pénicilline résistante aux pénicillinases staphylococciques : inhibe la synthèse de la paroi, bactéricide sur Staphylococcus aureus sensible à la méticilline.", "Infections cutanées et des tissus mous (impétigo étendu, furoncle, cellulite), ostéomyélite, staphylococcies à SASM.", "Adulte 500 mg-1 g toutes les 6 h (oral, à jeun) ou 1-2 g IV toutes les 4-6 h ; enfant 50-100 mg/kg/j en 4 prises.", "CI : allergie aux pénicillines. Inactive sur SARM. Troubles digestifs, hépatite cholestatique rare."),
"cefalexine": ("Céfalexine", AB, "Céphalosporines de 1re génération", "Céphalosporine de 1re génération : inhibe la synthèse de la paroi bactérienne ; actif sur staphylocoques et streptocoques sensibles, certains Gram −.", "Infections cutanées et des tissus mous, infections urinaires non compliquées, infections respiratoires hautes, ostéo-articulaires (relais).", "Adulte 250-500 mg toutes les 6 h ; enfant 25-50 mg/kg/j en 2-4 prises.", "CI : allergie aux céphalosporines ; prudence si allergie sévère aux pénicillines. Troubles digestifs ; adapter en insuffisance rénale."),
"cefixime": ("Céfixime", AB, "Céphalosporines de 3e génération (orales)", "Céphalosporine orale de 3e génération : inhibe la synthèse de la paroi, bactéricide sur entérobactéries, H. influenzae, gonocoque, streptocoques.", "Infections urinaires hautes et basses, otite moyenne, pharyngite, pneumonie légère, gonococcie non compliquée, fièvre typhoïde.", "Adulte 400 mg/j en 1-2 prises ; enfant 8 mg/kg/j en 1-2 prises.", "CI : allergie aux céphalosporines. Diarrhée, adapter en insuffisance rénale."),
"cefotaxime": ("Céfotaxime", AB, "Céphalosporines de 3e génération (injectables)", "Céphalosporine de 3e génération injectable : bactéricide par inhibition de la synthèse de la paroi ; large spectre, bonne diffusion méningée.", "Méningite bactérienne, septicémie, infections néonatales, pneumonie sévère, infections intra-abdominales et urinaires compliquées.", "Adulte 1-2 g IV/IM toutes les 8 h (jusqu'à 12 g/j) ; enfant 100-200 mg/kg/j en 3-4 doses (méningite : 200 mg/kg/j).", "CI : allergie aux céphalosporines. Diarrhée, neutropénie en cure prolongée, adapter en insuffisance rénale."),
"ceftriaxone": ("Ceftriaxone", AB, "Céphalosporines de 3e génération (injectables)", "Céphalosporine de 3e génération : inhibe la synthèse de la paroi bactérienne, bactéricide, longue demi-vie (1 injection/j), bonne diffusion méningée.", "Méningite, septicémie, pneumonie sévère, fièvre typhoïde, gonococcie, pyélonéphrite, infections intra-abdominales, prophylaxie chirurgicale.", "Adulte 1-2 g/j IV ou IM en 1 injection (méningite : 2 g toutes les 12 h) ; enfant 50-100 mg/kg/j (méningite : 100 mg/kg/j).", "CI : allergie aux céphalosporines ; ne pas administrer avec du calcium IV chez le nouveau-né ; prudence si hyperbilirubinémie néonatale. Lithiase biliaire réversible, diarrhée."),
"chloramphenicol": ("Chloramphénicol", AB, "Phénicolés", "Inhibe la synthèse protéique bactérienne (sous-unité 50S du ribosome) ; bactériostatique, bonne diffusion tissulaire et méningée.", "Méningite bactérienne (en l'absence d'alternative), fièvre typhoïde, rickettsioses, peste, choléra grave ; formes huileuses IM en épidémie de méningite.", "Adulte 50 mg/kg/j en 4 prises (max 4 g/j) ; enfant 50-100 mg/kg/j en 4 prises ; nouveau-né : dose réduite (25 mg/kg/j).", "Toxicité hématologique (aplasie, dose-dépendante) : numération surveillée ; syndrome gris du nouveau-né ; CI : 1er trimestre et fin de grossesse, nouveau-né prématuré."),
"ciprofloxacine": ("Ciprofloxacine", AB, "Fluoroquinolones", "Inhibe l'ADN gyrase et la topo-isomérase IV bactériennes : bactéricide, très actif sur entérobactéries et Pseudomonas aeruginosa.", "Infections urinaires (cystite, pyélonéphrite), prostatite, diarrhée invasive/typhoïde, infections osseuses et abdominales, charbon, méningococcie (prophylaxie).", "Adulte 250-750 mg 2x/j par voie orale ; IV 200-400 mg toutes les 8-12 h ; enfant : usage restreint (10-15 mg/kg 2x/j si indication précise).", "CI : grossesse, allaitement, enfant (sauf indication précise), antécédent de tendinopathie aux quinolones. Tendinite, QT long, neuropathie, hypoglycémie ; espacer des sels de fer/calcium/antiacides (2 h)."),
"azithromycine": ("Azithromycine", AB, "Macrolides (azalides)", "Inhibe la synthèse protéique bactérienne (sous-unité 50S) ; bactériostatique à longue demi-vie tissulaire ; actif sur germes atypiques, Chlamydia, Salmonella typhi.", "Pneumonie atypique, angine, infections génitales à Chlamydia, trachome, typhoïde non compliquée, coqueluche, pian.", "Adulte 500 mg 1x/j 3 jours ou 1 g en dose unique (Chlamydia) ; enfant 10 mg/kg/j 3 jours (trachome/pian : 20-30 mg/kg dose unique).", "CI : allergie aux macrolides. Allongement du QT, troubles digestifs, hépatotoxicité rare."),
"erythromycine": ("Érythromycine", AB, "Macrolides", "Macrolide : inhibe la synthèse protéique (sous-unité 50S), bactériostatique ; alternative en cas d'allergie aux pénicillines.", "Angine, infections cutanées, coqueluche, diphtérie, infections à germes atypiques, chancre mou, relais de la pénicilline en cas d'allergie.", "Adulte 250-500 mg toutes les 6 h ; enfant 30-50 mg/kg/j en 3-4 prises.", "Troubles digestifs fréquents ; QT long ; nombreuses interactions (inhibiteur CYP3A4) : carbamazépine, théophylline, statines, etc."),
"doxycycline": ("Doxycycline", AB, "Cyclines", "Inhibe la synthèse protéique bactérienne (sous-unité 30S) : bactériostatique à large spectre, actif sur germes intracellulaires.", "Infections à Chlamydia, rickettsioses, brucellose, choléra, paludisme (association à la quinine), prophylaxie palustre, syphilis (allergie aux pénicillines), acné.", "Adulte 100 mg 2x/j (ou 200 mg/j) ; prophylaxie palustre 100 mg/j ; enfant > 8 ans : 2-4 mg/kg/j.", "CI : grossesse, allaitement, enfant < 8 ans (dents, os). Photosensibilisation, œsophagite (boire un grand verre d'eau) ; espacer des sels de fer/calcium."),
"tetracycline": ("Tétracycline", AB, "Cyclines", "Inhibe la synthèse protéique (sous-unité 30S) ; bactériostatique. En pommade ophtalmique : antibiotique local.", "Pommade ophtalmique 1 % : conjonctivite bactérienne, trachome ; prophylaxie de l'ophtalmie du nouveau-né selon protocole.", "Pommade ophtalmique : 1 application 2-4x/j dans le cul-de-sac conjonctival ; trachome : 2x/j pendant 6 semaines.", "Hypersensibilité ; ne pas porter de lentilles pendant le traitement ; usage local uniquement."),
"gentamicine": ("Gentamicine", AB, "Aminosides", "Aminoside : se lie à la sous-unité 30S et provoque des erreurs de lecture ; bactéricide concentration-dépendant sur bacilles Gram −, synergique avec les bêta-lactamines.", "Septicémies, infections néonatales (avec ampicilline), pyélonéphrite sévère, infections abdominales, endocardite (synergie) ; collyre/gouttes : infections oculaires/auriculaires.", "Adulte 3-5 mg/kg/j en 1 injection IM/IV ; nouveau-né 4-5 mg/kg/j en 1 dose ; collyre : 1-2 gouttes 3-4x/j.", "Néphrotoxicité et ototoxicité : doser la créatinine, adapter à la fonction rénale ; CI : grossesse (toxicité fœtale), myasthénie ; limiter à 7-10 jours."),
"metronidazole": ("Métronidazole", AB, "Nitro-imidazolés", "Dérivé nitro-imidazolé réduit dans les germes anaérobies : lésions de l'ADN, bactéricide et antiparasitaire (amibes, Giardia, Trichomonas).", "Amibiase, giardiase, trichomonase, vaginose bactérienne, infections à anaérobies (abdominales, gynécologiques), colite à C. difficile, éradication d'H. pylori.", "Adulte 400-500 mg 3x/j (7-10 j) ; amibiase 750 mg 3x/j 5-10 j ; enfant 20-30 mg/kg/j en 3 prises ; IV 500 mg toutes les 8 h.", "Éviter l'alcool (effet antabuse) ; goût métallique ; neuropathie en cure prolongée ; prudence au 1er trimestre."),
"cotrimoxazole": ("Cotrimoxazole (sulfaméthoxazole + triméthoprime)", AB, "Sulfamides + diaminopyrimidines", "Blocage séquentiel de la synthèse de l'acide folique bactérien (sulfaméthoxazole + triméthoprime) : bactéricide à large spectre.", "Infections urinaires, bronchites, pneumocystose (traitement et prophylaxie), prophylaxie des infections opportunistes chez le PVVIH, diarrhées bactériennes, nocardiose.", "Adulte 960 mg (800/160) 2x/j ; prophylaxie VIH : 960 mg/j ; enfant : 24-30 mg/kg/j (sulfaméthoxazole + triméthoprime) en 2 prises.", "CI : nouveau-né < 6 semaines, insuffisance rénale ou hépatique sévère, déficit en G6PD, allergie aux sulfamides, 1er trimestre/fin de grossesse. Rash (syndrome de Stevens-Johnson), hyperkaliémie, cytopénies."),
"nitrofurantoine": ("Nitrofurantoïne", AB, "Antiseptiques urinaires", "Réduite dans les bactéries en dérivés réactifs qui altèrent ADN et ribosomes ; concentration urinaire élevée, bactéricide sur E. coli.", "Cystite aiguë non compliquée, prophylaxie des infections urinaires récidivantes.", "Adulte 50-100 mg 4x/j au repas (5-7 jours) ; formes LP 100 mg 2x/j ; enfant 3-5 mg/kg/j.", "CI : insuffisance rénale (clairance < 45 mL/min), déficit en G6PD, nouveau-né, fin de grossesse. Troubles digestifs, pneumopathie et neuropathie en cure prolongée."),
"quinine-dichlorhydrate": ("Quinine (dichlorhydrate)", "Antipaludiques", "Alcaloïdes du quinquina", "Schizonticide sanguin : interfère avec la détoxification de l'hème dans la vacuole digestive de Plasmodium.", "Paludisme grave à P. falciparum (quand l'artésunate IV est indisponible), paludisme non compliqué (2e ligne).", "Charge 20 mg de sel/kg en perfusion IV de 4 h dans glucosé 5 %, puis 10 mg/kg toutes les 8 h ; relais oral jusqu'à 7 jours. Jamais en bolus IV.", "Hypoglycémie, QT long, cinchonisme (acouphènes), hypotension si injection rapide ; surveillance glycémique."),
"artemether-lumefantrine": ("Artéméther + Luméfantrine", "Antipaludiques", "Combinaisons thérapeutiques à base d'artémisinine (CTA)", "Dérivé de l'artémisinine à action parasiticide rapide + antipaludique à élimination lente (luméfantrine) qui évite la recrudescence et la résistance.", "Paludisme non compliqué à P. falciparum (1re ligne).", "Cure de 3 jours (6 prises à 0, 8, 24, 36, 48, 60 h) ; dose selon le poids : 5-14 kg 1 cp, 15-24 kg 2 cp, 25-34 kg 3 cp, ≥ 35 kg 4 cp de 20/120 mg par prise ; à prendre avec un repas gras.", "CI : paludisme grave, 1er trimestre (sauf absence d'alternative), QT long. Interactions avec inducteurs/inhibiteurs du CYP3A4."),
"artesunate-inj": ("Artésunate injectable", "Antipaludiques", "Dérivés de l'artémisinine", "Dérivé hydrosoluble de l'artémisinine : parasiticide rapide sur toutes les formes sanguines de Plasmodium, y compris les formes séquestrées.", "Paludisme grave à P. falciparum (traitement de 1re ligne chez l'adulte et l'enfant, y compris la femme enceinte).", "2,4 mg/kg IV (ou IM) à 0, 12 et 24 h, puis 1x/j jusqu'à relais oral par CTA complet (3 jours) ; enfant < 20 kg : 3 mg/kg/dose.", "Anémie hémolytique retardée (surveiller 4 semaines) ; reconstitution extemporanée dans bicarbonate puis NaCl/glucose."),
"sulfadoxine-pyrimethamine": ("Sulfadoxine + Pyriméthamine", "Antipaludiques", "Antifoliniques (TPIg)", "Blocage séquentiel de la synthèse de l'acide folique du parasite (DHPS et DHFR) ; schizonticide à action lente.", "Traitement préventif intermittent du paludisme chez la femme enceinte (TPIg) dès le 2e trimestre ; chimioprévention saisonnière (avec amodiaquine) chez l'enfant.", "TPIg : 3 comprimés (1500/75 mg) en 1 prise, à chaque visite prénatale au moins 1 mois d'intervalle, dès 13 semaines de grossesse ; sous supervision.", "CI : allergie aux sulfamides, 1er trimestre, VIH sous cotrimoxazole (pas d'association), insuffisance rénale ou hépatique sévère. Rash cutané grave rare."),
"albendazole": ("Albendazole", "Antiparasitaires", "Anthelminthiques", "Se lie à la bêta-tubuline des nématodes, bloque la polymérisation des microtubules et l'absorption du glucose : effet vermicide.", "Ascaridiase, ankylostomiase, trichocéphalose, oxyurose, strongyloïdose, filarioses (association), hydatidose, neurocysticercose.", "400 mg en dose unique (nématodes intestinaux ; 200 mg avant 24 mois) ; 400 mg 2x/j pour strongyloïdose/hydatidose selon protocole.", "CI : 1er trimestre de grossesse. Hépatotoxicité en cure longue (surveiller les transaminases) ; prendre avec un repas gras pour les formes tissulaires."),
"mebendazole": ("Mébendazole", "Antiparasitaires", "Anthelminthiques", "Inhibe la polymérisation de la tubuline et l'absorption du glucose chez les nématodes intestinaux.", "Ascaridiase, ankylostomiase, trichocéphalose, oxyurose (déparasitage de masse).", "500 mg en dose unique, ou 100 mg 2x/j pendant 3 jours ; oxyurose : 100 mg en 1 prise répétée à 2 semaines.", "CI : 1er trimestre de grossesse, enfant < 1 an (selon notice). Troubles digestifs transitoires."),
"praziquantel": ("Praziquantel", "Antiparasitaires", "Anthelminthiques", "Augmente la perméabilité membranaire au calcium du ver : contracture et paralysie spastique du trématode/cestode, puis lyse du tégument.", "Bilharziose (schistosomoses), téniasis, distomatoses, cysticercose selon protocole.", "Bilharziose : 40 mg/kg en dose unique (S. mansoni, S. haematobium) ; téniasis : 5-10 mg/kg en dose unique ; à prendre avec un repas.", "Somnolence, vertiges (éviter conduite 24 h) ; prudence en cysticercose oculaire."),
"pyrantel": ("Pyrantel (embonate)", "Antiparasitaires", "Anthelminthiques", "Agoniste nicotinique : paralysie spastique des nématodes, éliminés par le péristaltisme.", "Ascaridiase, oxyurose, ankylostomiase.", "10 mg/kg (base) en dose unique (max 1 g) ; ankylostomiase : 11 mg/kg/j 3 jours ; répéter à 2 semaines pour l'oxyurose.", "Troubles digestifs, céphalées ; prudence en insuffisance hépatique."),
"permethrine": ("Perméthrine", "Antiparasitaires", "Scabicides et pédiculicides", "Pyréthrinoïde de synthèse : paralyse les canaux sodiques voltage-dépendants du parasite (sarcopte, pou).", "Gale (crème 5 %), pédiculose du cuir chevelu (lotion 1 %).", "Gale : application sur tout le corps (cou aux orteils) 8-14 h puis rinçage, à répéter à J7 ; pédiculose : lotion 10 min puis rinçage, répéter à J7-10.", "Prurit post-scabieux transitoire normal ; éviter yeux et muqueuses ; traiter l'entourage et la literie."),
"benzoate-benzyle": ("Benzoate de benzyle", "Antiparasitaires", "Scabicides et pédiculicides", "Acaricide et pédiculicide local : toxique sur les sarcoptes et les poux.", "Gale (lotion 25 %), pédiculose.", "Application sur tout le corps à J1 et J2 (ou 24 h) puis rinçage ; diluer chez l'enfant selon l'âge ; répéter à J7.", "Irritation cutanée ; ne pas utiliser sur peau lésée, chez le nourrisson non dilué ; éviter yeux."),
"clotrimazole": ("Clotrimazole", "Antifongiques", "Azolés locaux", "Imidazolé : inhibe la synthèse de l'ergostérol de la membrane fongique (14-α-déméthylase) ; fongistatique à fongicide.", "Mycoses cutanées (teignes, pityriasis versicolor, candidoses), candidose vulvo-vaginale (ovules/comprimés vaginaux).", "Crème 1 % : 2-3 applications/j 2-4 semaines ; ovule 500 mg dose unique ou 100 mg le soir 6-7 jours.", "Irritation locale ; éviter les préservatifs en latex pendant le traitement vaginal."),
"miconazole": ("Miconazole (nitrate)", "Antifongiques", "Azolés locaux", "Imidazolé antifongique : inhibe la synthèse de l'ergostérol ; actif sur dermatophytes et Candida.", "Mycoses cutanées, intertrigo, candidoses cutanéo-muqueuses.", "Crème 2 % : 2x/j 2 à 4 semaines, poursuivre 1 semaine après guérison.", "Irritation locale ; éviter le contact oculaire."),
"nystatine": ("Nystatine", "Antifongiques", "Polyènes", "Se lie à l'ergostérol de la membrane fongique et forme des pores ; fongicide sur Candida, non absorbée.", "Candidose oro-pharyngée, digestive, prophylaxie chez le nouveau-né et l'immunodéprimé.", "Suspension 100 000 UI/mL : nourrisson 1 mL 4x/j, enfant/adulte 4-6 mL 4x/j, garder en bouche ; 7 jours et 2 jours après guérison.", "Troubles digestifs à forte dose ; peu de toxicité systémique."),
"griseofulvine": ("Griséofulvine", "Antifongiques", "Antifongiques systémiques", "Se fixe sur la tubuline des champignons (arrêt de la mitose) et s'accumule dans la kératine : fongistatique sur dermatophytes.", "Teignes du cuir chevelu (Microsporum, Trichophyton), dermatophytoses étendues.", "Adulte 500-1000 mg/j ; enfant 10-20 mg/kg/j en 1-2 prises, au repas gras ; 6-8 semaines (teigne).", "CI : grossesse, porphyrie, insuffisance hépatique. Céphalées, photosensibilisation, interactions (inducteur CYP) ; contraception renforcée."),
"aciclovir": ("Aciclovir", "Antiviraux", "Antiherpétiques", "Analogue nucléosidique de la guanosine phosphorylé par la thymidine kinase virale : inhibe l'ADN polymérase virale (HSV, VZV).", "Herpès génital et labial, zona, varicelle de l'immunodéprimé, encéphalite herpétique (IV), herpès néonatal.", "Herpès : 200 mg 5x/j 5-10 jours (ou 400 mg 3x/j) ; zona : 800 mg 5x/j 7 jours ; encéphalite : 10 mg/kg IV toutes les 8 h.", "Adapter en insuffisance rénale ; hydratation (cristallurie IV) ; céphalées, nausées."),
"abacavir-lamivudine": ("Abacavir + Lamivudine", "Antirétroviraux", "Inhibiteurs nucléosidiques (INTI)", "Deux analogues nucléosidiques : inhibition de la transcriptase inverse du VIH (arrêt de l'élongation de l'ADN proviral).", "Infection à VIH-1 chez l'enfant (base du traitement pédiatrique, avec dolutégravir).", "Forme dispersible 120/60 mg : dose selon le poids (grille OMS pédiatrique), 1 prise/j.", "Réaction d'hypersensibilité à l'abacavir (arrêt définitif si fièvre + rash + signes digestifs/respiratoires) ; CI : insuffisance hépatique sévère."),
"dolutegravir": ("Dolutégravir", "Antirétroviraux", "Inhibiteurs d'intégrase (INSTI)", "Inhibiteur du transfert de brin de l'intégrase du VIH : empêche l'intégration de l'ADN viral dans le génome de la cellule hôte.", "Infection à VIH-1, en association à deux INTI (1re et 2e ligne selon OMS), adulte et enfant ≥ 4 semaines.", "Adulte 50 mg 1x/j ; enfant selon poids (comprimés dispersibles 10 mg) ; 50 mg 2x/j si rifampicine ; avec ou sans repas.", "Espacer de 2 h des sels de fer/calcium/antiacides ; troubles du sommeil, céphalées, prise de poids ; hypersensibilité rare."),
"tenofovir-lamivudine-dolutegravir": ("Ténofovir + Lamivudine + Dolutégravir (TLD)", "Antirétroviraux", "Associations fixes (schéma de 1re ligne)", "Deux INTI (ténofovir disoproxil, lamivudine) + un inhibiteur d'intégrase (dolutégravir) : bloquent la transcriptase inverse et l'intégration du VIH.", "Infection à VIH-1, traitement de 1re ligne de l'adulte et de l'adolescent ≥ 30 kg (schéma OMS préféré).", "1 comprimé (300/300/50 mg) 1x/j, à heure fixe ; 50 mg supplémentaires de dolutégravir 12 h plus tard si rifampicine.", "Surveiller la fonction rénale (ténofovir) ; CI : clairance < 50 mL/min ; hépatite B : ne pas arrêter brutalement (poussée) ; espacer des polycations."),
}
